import { z } from "zod";
import type { SupabaseClient } from "@supabase/supabase-js";
import { GatewayError, type Gateway } from "../ai/gateway.ts";
import type { ItemSolveOutput, ItemsGenerateInput, ItemsGenerateOutput } from "../ai/skills/items.ts";
import type { Database, Json } from "../db/types.ts";
import type { LessonSpec } from "../dsl/schema.ts";
import { checkItems, itemRows, solveQuestions } from "../items/check.ts";
import type { PrivateLessonRepo } from "../lessons/private.ts";
import type { LessonRepo } from "../lessons/repo.ts";
