// items_gen (F5-FR2, 04 §4.3, 10 MVP-02): practice questions for a topic once its lesson is
// published. items_generate writes them; item_solve answers them without seeing the answers; only
// items that pass the self-consistency check and agree with the solve are saved (05 §4). Grounded in
// the student's own materials for a private lesson (items owned by the student), else shared.

export const itemsGenPayload = z.object({
  concept_id: z.string().uuid(),
  lesson_id: z.string().uuid(),
  course_id: z.string().uuid().nullable().default(null),
  owner_id: z.string().uuid().nullable().default(null),
});

const MSG = { failed: "Ifiok couldn't write practice questions for this topic just now." } as const;

export type ItemsRepo = {
  loadLesson(
    lessonId: string,
  ): Promise<{ conceptId: string; ownerId: string | null; status: string; spec: LessonSpec } | null>;
  /** Generated items already saved for this concept and owner (null = shared). */
  countGenerated(conceptId: string, ownerId: string | null): Promise<number>;
  insert(rows: ReturnType<typeof itemRows>): Promise<void>;
};

export function createSupabaseItemsRepo(db: SupabaseClient<Database>): ItemsRepo {
  return {
    async loadLesson(lessonId) {
      const { data, error } = await db
        .from("lessons")
        .select("concept_id, owner_id, status, spec")
        .eq("id", lessonId)
        .maybeSingle();
      if (error) throw new Error("Couldn't load the lesson");
      return data
        ? {
            conceptId: data.concept_id,
            ownerId: data.owner_id,
            status: data.status,
            spec: data.spec as unknown as LessonSpec,
          }
        : null;
    },
    async countGenerated(conceptId, ownerId) {
      let q = db
        .from("items")
        .select("id", { count: "exact", head: true })
        .eq("concept_id", conceptId)
        .eq("origin", "generated");
      q = ownerId ? q.eq("owner_id", ownerId) : q.is("owner_id", null);
      const { count, error } = await q;
      if (error) throw new Error("Couldn't count items");
      return count ?? 0;
    },
    async insert(rows) {
      if (rows.length === 0) return;
      const { error } = await db.from("items").insert(rows);
      if (error) throw new Error("Couldn't save practice questions");
    },
  };
}

/** What the lesson taught, for the item writer: objective, screen titles, worked examples, checkpoints. */
export function lessonSummary(spec: LessonSpec): string {
  const lines = [`Lesson: ${spec.title}`, `Objective: ${spec.objective}`];
  for (const screen of spec.screens) {
    const bits: string[] = [];
    for (const block of screen.blocks) {
      if (block.type === "prose" || block.type === "callout") bits.push(block.md.slice(0, 200));
      else if (block.type === "math") bits.push(block.latex);
      else if (block.type === "checkpoint") bits.push(`Checkpoint: ${block.item.stem_md.slice(0, 200)}`);
    }
    lines.push(`- ${screen.id}: ${bits.join(" | ")}`);
  }
  return lines.join("\n").slice(0, 4000);
}

export type ItemsGenDeps = {
  items: ItemsRepo;
  lessons: Pick<LessonRepo, "loadConcept" | "sharedSources">;
  privateLessons: Pick<PrivateLessonRepo, "config" | "sources">;
  gateway: Pick<Gateway, "run">;
  now?: () => Date;
};

export function createItemsGenHandler(deps: ItemsGenDeps): JobHandler {
  return {
    async run(job) {
      const parsed = itemsGenPayload.safeParse(job.payload);
      if (!parsed.success) throw new JobFailure("bad_payload", MSG.failed, false);
      const p = parsed.data;
      // Guardrail 7: private items belong to the job owner.
      if (p.owner_id && job.ownerId !== p.owner_id) throw new JobFailure("payload_owner_mismatch", MSG.failed, false);

      const lesson = await deps.items.loadLesson(p.lesson_id);
      if (
        !lesson ||
        lesson.status !== "published" ||
        lesson.conceptId !== p.concept_id ||
        lesson.ownerId !== p.owner_id
      ) {
        return { kind: "done", result: { skipped: "lesson_unavailable" } satisfies Json };
      }
      const cfg = await deps.privateLessons.config();
      const have = await deps.items.countGenerated(p.concept_id, p.owner_id);
      if (have >= cfg.items_per_topic)
        return { kind: "done", result: { skipped: "enough_items", have } satisfies Json };

      const concept = await deps.lessons.loadConcept(p.concept_id);
      if (!concept) throw new JobFailure("concept_missing", MSG.failed, false);
      const chunks = p.owner_id
        ? await deps.privateLessons.sources({ userId: p.owner_id, courseId: p.course_id }, p.concept_id, cfg)
        : await deps.lessons.sharedSources(p.concept_id);

      const input: ItemsGenerateInput = {
        concept: {
          title: concept.title,
          description: concept.description,
          subject: concept.subject,
          level_band: concept.level_band,
        },
        lesson_summary: lessonSummary(lesson.spec),
        chunks: chunks.map((c) => ({ id: c.id, content: c.content })),
        count: cfg.items_per_topic - have,
        numeric_allowed: subjectProfile(concept.subject) === "stem",
      };
      const userId = p.owner_id;

      let generated: ItemsGenerateOutput["items"];
      let solved: ItemSolveOutput["answers"];
      try {
        generated = (
          await deps.gateway.run<ItemsGenerateOutput>("items_generate", {
            userId,
            mode: "job",
            attempt: job.attempts,
            input,
          })
        ).output.items;
        solved = (
          await deps.gateway.run<ItemSolveOutput>("item_solve", {
            userId,
            mode: "job",
            attempt: job.attempts,
            input: { questions: solveQuestions(generated) },
          })
        ).output.answers;
      } catch (err) {
        if (err instanceof GatewayError && err.code === "library_budget") {
          const now = deps.now?.() ?? new Date();
          return {
            kind: "defer",
            seconds: secondsUntilLagosMidnight(now),
            result: { waiting: "library_budget", day: lagosDay(now) },
          };
        }
        throw new JobFailure(err instanceof GatewayError ? err.code : "items_failed", MSG.failed);
      }

      // Only chunk ids the writer was given may be cited.
      const allowed = new Set(chunks.map((c) => c.id));
      const { accepted, dropped } = checkItems(
        generated.map((i) => ({ ...i, source_refs: i.source_refs.filter((id) => allowed.has(id)) })),
        solved,
      );
      await deps.items.insert(
        itemRows(accepted, { conceptId: p.concept_id, ownerId: p.owner_id, courseId: p.owner_id ? p.course_id : null }),
      );
      return {
        kind: "done",
        result: {
          generated: generated.length,
          published: accepted.length,
          dropped: dropped.map((d) => d.reason),
        } satisfies Json,
      };
    },
  };
}
